std::string wire(const hud::Document& doc){std::string text='"'+doc.title+"\" {\n";if(!doc.note.empty())text+="\"description\" \""+doc.note+"\"\n";if(doc.pinned)text+="\"pinned_rows\" \""+std::to_string(doc.pinned)+"\"\n";if(!doc.sections.empty()){std::string sections;for(auto n:doc.sections){if(!sections.empty())sections+=',';sections+=std::to_string(n);}text+="\"page_starts\" \""+sections+"\"\n";}for(auto& row:doc.rows)text+='"'+row.label+"\" { \"user_data\" \""+[] (uintptr_t n){char out[32];std::snprintf(out,sizeof(out),"%lx",static_cast<unsigned long>(n));return std::string(out);}(row.action)+"\" }\n";return text+"}";}
