 follow::Settings target;target.enabled=true;target.bobEnabled=true;target.bobPeriod=2;target.bobAmplitude=33;target.target={true,4,12345};target.offset={1,2,3};target.size=2;auto followDefault=reset::followAppearance(target);assert(followDefault.enabled&&followDefault.target.handle==target.target.handle&&followDefault.offset.x==1&&followDefault.size==2&&!followDefault.bobEnabled&&followDefault.bobPeriod==.5f&&followDefault.bobAmplitude==1);
 auto all=reset::all(current);auto expected=defaults;expected.visualPresets=current.visualPresets;assert(encodeConfig(all)==encodeConfig(expected));assert(!all.sync.enabled&&!all.sync.discover&&!all.sync.apply&&!all.sync.autoSearch&&!all.autoFollow.enabled&&all.autoFollow.rules.empty()&&all.visualPresets==current.visualPresets);
