 auto presets=*catalog::page(5010,defaults);assert(presets.rows.size()==18&&presets.pinned==1);auto decoded=hud::document(wire(presets));assert(decoded.rows.size()==18&&decoded.pinned==1&&decoded.sections==presets.sections);hud::MenuStack stack;auto ranges=hud::pageRanges(decoded);assert(ranges.size()==3&&ranges[0].second-ranges[0].first==7&&ranges[1].second-ranges[1].first==6&&ranges[2].second-ranges[2].first==4);
 for(unsigned sheet=0;sheet<3;++sheet){stack.current().sheet=sheet;auto visible=stack.visible(decoded);assert(visible.size()<=9&&stack.select(decoded,1)==6000);for(size_t digit=2;digit<=visible.size();++digit)assert(stack.select(decoded,digit)>=6100&&stack.select(decoded,digit)<=6116);}
