 for(unsigned i=0;i<catalog::FieldCount;++i){auto field=catalog::Field(i);auto c=current;c.wallIndependentTiming=true;auto n=catalog::numberField(c,field);auto action=6600+i*5;assert(catalog::adjust(c,action+3));assert(std::abs(catalog::numberField(c,field).value-n.low)<.0001f);for(int press=0;press<100;++press)catalog::adjust(c,action);assert(catalog::numberField(c,field).value>=n.low);assert(catalog::adjust(c,action+4));assert(std::abs(catalog::numberField(c,field).value-n.high)<.0001f);catalog::adjust(c,action+2);assert(std::abs(catalog::numberField(c,field).value-catalog::numberField(defaults,field).value)<.0001f);assert(!hud::opensChild(action)&&hud::opensChild(catalog::fieldPage(field)));assert(sync::settingsJson(c.sync)==sync::settingsJson(current.sync));}
