 std::set<uintptr_t> seen;std::vector<uintptr_t> pages{5000,5100,5200,5300,5400,5500};while(!pages.empty()){auto id=pages.back();pages.pop_back();if(!seen.insert(id).second)continue;auto d=catalog::page(id,defaults);if(!d)continue;assert(navigation::page(id));assert(hud::document(wire(*d)).rows.size()==d->rows.size());for(auto [first,last]:hud::pageRanges(*d))assert(last-first+d->pinned<=9);for(auto& row:d->rows){assert(!build::diagnosticAction(row.action));if(navigation::page(row.action))pages.push_back(row.action);}}
 if(argc==2&&std::string(argv[1])=="--dump"){nlohmann::json out=nlohmann::json::array();for(auto id:{0,5000,5010,5100,5200,5300,5400,5500,5501}){auto d=id?*catalog::page(id,defaults):catalog::root(defaults,u8"保存设置: [已保存]",false);auto rows=nlohmann::json::array();for(auto& row:d.rows)rows.push_back({{"label",row.label},{"action",row.action}});out.push_back({{"page",id},{"title",d.title},{"rows",rows}});}std::cout<<out.dump();return 0;}
 std::cout<<"Passed: installed defaults, scoped reset/favorites/layout/network isolation, 17 direct-apply themes with pinned scope and grouped pagination, bounded numeric controls, dependency gating and reachable menu graph\n";
